  "Error": "Error",
  "ESB inventory valuation per outlet location × item × opname period (1–7, 8–14, 15–21, 22–end of month): opening stock, purchases/transfers, recipe usage of POS sales (sales HPP), item journals, opname differences, closing stock — at ESB HPP (moving average cost). Synced nightly at 04:15 WIB; Cost Control recalculated at 05:10 WIB (last 10 days) and every Sunday 06:00 WIB (last 40 days).": "Valuasi persediaan ESB per lokasi outlet × item × periode opname (1–7, 8–14, 15–21, 22–akhir bulan): stok awal, pembelian/transfer, pemakaian resep dari penjualan POS (HPP penjualan), item journal, selisih opname, stok akhir — dengan HPP ESB (biaya rata-rata bergerak). Disinkronkan setiap malam pukul 04:15 WIB; Cost Control dihitung ulang pukul 05:10 WIB (10 hari terakhir) dan setiap Minggu pukul 06:00 WIB (40 hari terakhir).",
  "ESB inventory valuation per outlet location × product × opname period (days 1–7, 8–14, 15–21, 22–end), ESB stock opname documents, and Sales from the aggregates.": "Valuasi persediaan ESB per lokasi outlet × produk × periode opname (hari 1–7, 8–14, 15–21, 22–akhir), dokumen stock opname ESB, dan Penjualan dari agregat.",
  "ESB item journals (Item Usage): waste, R&D, marketing, QC, staff meals…": "Item journal ESB (Item Usage): waste, R&D, marketing, QC, makan staf…",
  "ESB POS transactions (integration_esb.transactions_pos_sales), synced from ESB every 15 minutes during trading hours (:05 today + yesterday, :20 / :35 / :50 today, 06:00–24:00 WIB; hourly at night) and re-synced for the last 7 days every night at 02:15 WIB.": "Transaksi POS ESB (integration_esb.transactions_pos_sales), disinkronkan dari ESB setiap 15 menit selama jam operasional (:05 hari ini + kemarin, :20 / :35 / :50 hari ini, 06:00–24:00 WIB; per jam pada malam hari) dan disinkronkan ulang untuk 7 hari terakhir setiap malam pukul 02:15 WIB.",
  "ESB POS transactions of today, read directly (not the aggregates); updated after every sync — every 15 minutes during trading hours (06:00–24:00 WIB) — and pushed to the page in real time within ~15 seconds.": "Transaksi POS ESB hari ini, dibaca langsung (bukan dari agregat); diperbarui setelah setiap sinkronisasi — setiap 15 menit selama jam operasional (06:00–24:00 WIB) — dan dikirim ke halaman secara real time dalam ~15 detik.",
  "ESB purchases and transfers into the outlet (from Warehouse, CK Espresso, CK Food) at transfer price.": "Pembelian dan transfer ESB ke outlet (dari Warehouse, CK Espresso, CK Food) dengan harga transfer.",
  "ESB stock opname documents: posted (Authorized/Finished) differences are final; Draft/New ones are counted as pending (the period is provisional until they are posted in ESB).": "Dokumen stock opname ESB: selisih yang sudah diposting (Authorized/Finished) bersifat final; yang masih Draft/New dihitung sebagai pending (periodenya sementara sampai diposting di ESB).",
  "ESB stock opname, production, receipt, purchase, transfer and item journal documents; ESB inventory valuation.": "Dokumen ESB untuk stock opname, produksi, penerimaan, pembelian, transfer dan item journal; valuasi persediaan ESB.",
  "Estimate": "Perkiraan",
  "Estimated purchases for the next 1 / 2 / 4 weeks per outlet, to plan budgets and orders.": "Perkiraan pembelian untuk 1 / 2 / 4 minggu ke depan per outlet, untuk merencanakan anggaran dan pemesanan.",
  "Even small progress counts on tiring days. Be kind to yourself.": "Kemajuan kecil tetap berarti di hari yang melelahkan. Bersikap baiklah pada diri sendiri.",
  "Evening check-in: take a moment to celebrate what went well today.": "Cek malam: luangkan waktu merayakan apa yang berjalan baik hari ini.",
