  "Follows the date range (every opname period starting in it) and the branch filter. Network totals only include locations with POS sales; bulk-order / stock locations are listed under Data quality.": "Mengikuti rentang tanggal (setiap periode opname yang dimulai di dalamnya) dan filter cabang. Total jaringan hanya mencakup lokasi dengan penjualan POS; lokasi bulk-order / stok dicantumkan di Kualitas data.",
