  "What the outlets really used: recipe usage of what was sold, plus item journals (waste, R&D, marketing…), plus or minus what the stock opname found missing or extra.": "Apa yang benar-benar dipakai outlet: pemakaian resep dari yang terjual, ditambah item journal (waste, R&D, marketing…), ditambah atau dikurangi kekurangan atau kelebihan yang ditemukan saat stock opname.",
  "What the outlets received in the period. Same as the workbook \"COGS Value\" (Pembelian BB + Espresso + Dimsum); its \"COGS Ratio\" = purchases ÷ sales.": "Apa yang diterima outlet dalam periode. Sama dengan \"COGS Value\" di workbook (Pembelian BB + Espresso + Dimsum); \"COGS Ratio\"-nya = pembelian ÷ penjualan.",
  "What the outlets should have used: every menu sold × its recipe (BOM) × the item's HPP. Depends on menu mix, recipes and purchase prices — not on how well the outlet is run.": "Apa yang seharusnya dipakai outlet: setiap menu terjual × resepnya (BOM) × HPP item. Bergantung pada komposisi menu, resep dan harga beli — bukan pada seberapa baik outlet dijalankan.",
  "What to correct in ESB so the figures are final and accurate. Every check names the document to fix.": "Apa yang perlu dikoreksi di ESB agar angka menjadi final dan akurat. Setiap pemeriksaan menyebutkan dokumen yang perlu diperbaiki.",
