  // User Accounts lines & menus (2026-11-02)
  "Menus per platform": "Menu per platform",
  "The tab of User Accounts the account is listed in; its branches are of this line": "Tab User Accounts tempat akun ini tercantum; cabangnya dari lini ini",
  "Menu display: ticked pages are shown in the menu. Unticked pages keep working (by their address, links and approvals) — only the menu gets shorter.": "Tampilan menu: halaman yang dicentang tampil di menu. Halaman yang tidak dicentang tetap berfungsi (lewat alamat, tautan dan approval) — hanya menunya yang lebih ringkas.",
  "Show every page ({0} hidden)": "Tampilkan semua halaman ({0} disembunyikan)",
  "Saved. The menus follow within a minute (after the next sign-in check).": "Tersimpan. Menu menyesuaikan dalam satu menit (setelah pengecekan login berikutnya).",
  "Where every page is shown in the menu: the portal, Operations or the Calf On The Road app. Only the menu changes; the access and the flows stay as they are.": "Tempat setiap halaman tampil di menu: portal, Operations atau aplikasi Calf On The Road. Hanya menu yang berubah; akses dan alur tetap seperti biasa.",
  // Outlet ratio header info (2026-11-02)
  "ESB POS: subtotal of the sales bills of the outlet in the period (synced daily, agg_sales_daily, type Sales). Same as the workbook column Sub Total (GROSS SALES).": "ESB POS: subtotal bill penjualan outlet pada periode (sinkron harian, agg_sales_daily, tipe Sales). Sama dengan kolom workbook Sub Total (GROSS SALES).",
  "Σ subtotal of the sales bills": "Σ subtotal bill penjualan",
  "Pendapatan when the MDR of the month is filled in, otherwise the ESB nett sales of the sales bills (marked ESB).": "Pendapatan bila MDR bulan tersebut diisi, selain itu nett sales ESB dari bill penjualan (bertanda ESB).",
  "Gross sales × (1 − MDR %)": "Gross sales × (1 − MDR %)",
  "Entered here by Cost Control per outlet and month (merchant discount rate of the payment channels). Editable when the period is within one month.": "Diisi di halaman ini oleh Cost Control per outlet dan bulan (merchant discount rate kanal pembayaran). Bisa diubah bila periode dalam satu bulan.",
  "ESB purchase invoices of the outlet from the supplier Calf Warehouse, by invoice date in the period: raw materials, packaging and supplies.": "Purchase invoice ESB outlet dari supplier Calf Warehouse, menurut tanggal invoice dalam periode: bahan baku, kemasan dan perlengkapan.",
  "ESB purchase invoices of the outlet from the supplier Calf Central Kitchen (espresso / premix), by invoice date in the period.": "Purchase invoice ESB outlet dari supplier Calf Central Kitchen (espresso / premix), menurut tanggal invoice dalam periode.",
  "ESB purchase invoices of the outlet from the supplier Calf Central Kitchen Food (dimsum), by invoice date in the period.": "Purchase invoice ESB outlet dari supplier Calf Central Kitchen Food (dimsum), menurut tanggal invoice dalam periode.",
  "Purchases of the outlet from the three internal suppliers; purchases from other suppliers are not included (Excel column Pembelian lain).": "Pembelian outlet dari tiga supplier internal; pembelian dari supplier lain tidak termasuk (kolom Excel Pembelian lain).",
  "Pembelian BB + Espresso + Dimsum": "Pembelian BB + Espresso + Dimsum",
  "Share of espresso in the purchases.": "Porsi espresso dalam pembelian.",
  "Espresso ÷ COGS value": "Espresso ÷ COGS value",
  "Raw materials and dimsum bought against the sales of the view (gross or net).": "Bahan baku dan dimsum yang dibeli terhadap penjualan tampilan (gross atau net).",
  "(Pembelian BB + Dimsum) ÷ sales": "(Pembelian BB + Dimsum) ÷ penjualan",
  "Espresso bought against the sales of the view.": "Espresso yang dibeli terhadap penjualan tampilan.",
  "Espresso ÷ sales": "Espresso ÷ penjualan",
  "Purchases against the sales of the view: what was bought, not yet what was used (see Usage ratio).": "Pembelian terhadap penjualan tampilan: yang dibeli, belum tentu yang terpakai (lihat Usage ratio).",
  "COGS value ÷ sales": "COGS value ÷ penjualan",
  "Stock value of the ESB stock opname document of the day before the period (the closest document from 2 days before to 1 day after), or the value corrected here with a reason (Corrected).": "Nilai stok dokumen stock opname ESB sehari sebelum periode (dokumen terdekat dari 2 hari sebelum hingga 1 hari sesudah), atau nilai yang dikoreksi di sini dengan alasan (Dikoreksi).",
  "Stock value of the ESB stock opname document of the last day of the period (the closest document from 2 days before to 1 day after), or the value corrected here with a reason (Corrected).": "Nilai stok dokumen stock opname ESB hari terakhir periode (dokumen terdekat dari 2 hari sebelum hingga 1 hari sesudah), atau nilai yang dikoreksi di sini dengan alasan (Dikoreksi).",
  "Σ qty × price of the stock opname lines": "Σ qty × harga baris stock opname",
  "What was really used: purchases plus the stock at the start minus the stock at the end, against the sales of the view. Empty when SO awal or SO akhir is missing.": "Pemakaian sebenarnya: pembelian ditambah stok awal dikurangi stok akhir, terhadap penjualan tampilan. Kosong bila SO awal atau SO akhir tidak ada.",
  "(COGS value + SO awal − SO akhir) ÷ sales": "(COGS value + SO awal − SO akhir) ÷ penjualan",
  "Positive: more was bought than used (stock grows); negative: stock was used up. Near 0: purchases follow the usage.": "Positif: pembelian lebih besar dari pemakaian (stok bertambah); negatif: stok terpakai. Mendekati 0: pembelian sesuai pemakaian.",
  "COGS ratio − Usage ratio": "COGS ratio − Usage ratio",
  "ESB POS: subtotal of the bills of type Other cost (non sales, e.g. compliments, staff meals) in the period.": "ESB POS: subtotal bill bertipe Other cost (non sales, mis. compliment, makan staf) pada periode.",
  "ESB item journal documents of the outlet in the period (waste, QC and other stock adjustments), valued at the line price.": "Dokumen item journal ESB outlet pada periode (waste, QC dan penyesuaian stok lain), dinilai dengan harga baris.",
  "Σ |qty × price| of the item journal lines": "Σ |qty × harga| baris item journal",
